// Lightweight Offline ZIP Archive Generator (Client-Side)
class SimpleZip {
  constructor() {
    this.files = [];
  }

  file(name, data) {
    this.files.push({ name, data });
  }

  async generateAsync(options = { type: 'blob' }) {
    const fileEntries = [];
    let centralDirSize = 0;
    let localOffset = 0;

    for (const f of this.files) {
      let bytes;
      if (f.data instanceof Blob) {
        const buffer = await f.data.arrayBuffer();
        bytes = new Uint8Array(buffer);
      } else if (f.data instanceof ArrayBuffer) {
        bytes = new Uint8Array(f.data);
      } else if (f.data instanceof Uint8Array) {
        bytes = f.data;
      } else {
        bytes = new TextEncoder().encode(String(f.data));
      }

      const nameBytes = new TextEncoder().encode(f.name);
      const crc = this.crc32(bytes);
      const size = bytes.length;

      // Local File Header
      const header = new Uint8Array(30 + nameBytes.length);
      const view = new DataView(header.buffer);
      view.setUint32(0, 0x04034b50, true); // signature
      view.setUint16(4, 20, true); // version needed
      view.setUint16(6, 0, true); // flags
      view.setUint16(8, 0, true); // compression (store)
      view.setUint16(10, 0, true); // time
      view.setUint16(12, 0, true); // date
      view.setUint32(14, crc, true); // crc-32
      view.setUint32(18, size, true); // compressed size
      view.setUint32(22, size, true); // uncompressed size
      view.setUint16(26, nameBytes.length, true); // filename length
      view.setUint16(28, 0, true); // extra field length
      header.set(nameBytes, 30);

      fileEntries.push({
        header,
        data: bytes,
        nameBytes,
        crc,
        size,
        offset: localOffset
      });

      localOffset += header.length + bytes.length;
    }

    // Build Central Directory
    const cdEntries = [];
    for (const entry of fileEntries) {
      const cdHeader = new Uint8Array(46 + entry.nameBytes.length);
      const view = new DataView(cdHeader.buffer);
      view.setUint32(0, 0x02014b50, true); // central header signature
      view.setUint16(4, 20, true); // version made by
      view.setUint16(6, 20, true); // version needed
      view.setUint16(8, 0, true); // flags
      view.setUint16(10, 0, true); // compression
      view.setUint16(12, 0, true); // time
      view.setUint16(14, 0, true); // date
      view.setUint32(16, entry.crc, true);
      view.setUint32(20, entry.size, true);
      view.setUint32(24, entry.size, true);
      view.setUint16(28, entry.nameBytes.length, true);
      view.setUint16(30, 0, true);
      view.setUint16(32, 0, true);
      view.setUint16(34, 0, true);
      view.setUint32(36, 0, true);
      view.setUint32(42, entry.offset, true);
      cdHeader.set(entry.nameBytes, 46);

      cdEntries.push(cdHeader);
      centralDirSize += cdHeader.length;
    }

    // End of Central Directory Record
    const eocd = new Uint8Array(22);
    const eocdView = new DataView(eocd.buffer);
    eocdView.setUint32(0, 0x06054b50, true); // EOCD signature
    eocdView.setUint16(4, 0, true); // disk number
    eocdView.setUint16(6, 0, true); // start disk
    eocdView.setUint16(8, fileEntries.length, true); // records on disk
    eocdView.setUint16(10, fileEntries.length, true); // total records
    eocdView.setUint32(12, centralDirSize, true); // central dir size
    eocdView.setUint32(16, localOffset, true); // offset of central dir
    eocdView.setUint16(20, 0, true); // comment length

    const parts = [];
    for (const e of fileEntries) {
      parts.push(e.header);
      parts.push(e.data);
    }
    for (const cd of cdEntries) {
      parts.push(cd);
    }
    parts.push(eocd);

    return new Blob(parts, { type: 'application/zip' });
  }

  crc32(buf) {
    let crc = -1;
    for (let i = 0; i < buf.length; i++) {
      let byte = buf[i];
      crc = (crc >>> 8) ^ SimpleZip.crcTable[(crc ^ byte) & 0xFF];
    }
    return (crc ^ (-1)) >>> 0;
  }
}

SimpleZip.crcTable = (() => {
  const table = new Uint32Array(256);
  for (let i = 0; i < 256; i++) {
    let c = i;
    for (let k = 0; k < 8; k++) {
      c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
    }
    table[i] = c;
  }
  return table;
})();

window.JSZip = SimpleZip;
